const leads = $('📧 Emails publics trouvés').all();
const catalog = $('🧭 Préparer recherches + catalogue').first().json.catalog || [];
const minScore = Number($('⚙️ Configuration prospection').first().json.minScore || 70);
const out = [];
for (let i = 0; i < $input.all().length; i++) {
  const lead = leads[i]?.json || {};
  const payload=$input.all()[i]?.json||{};
  let raw = String(payload?.choices?.[0]?.message?.content || '').trim();
  if(!raw) continue;
  raw = raw.replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'');
  const a=raw.indexOf('{'), b=raw.lastIndexOf('}');
  if(a>=0&&b>=a) raw=raw.slice(a,b+1);
  let ai;
  try { ai = JSON.parse(raw); } catch (e) { continue; }
  const score = Math.max(0, Math.min(100, Number(ai.score || 0)));
  const handle = String(ai.recommended_handle || '').trim();
  let product = catalog.find(p => p.handle === handle);
  if (!product && ai.recommended_title) {
    product = catalog.find(p => p.title.toLowerCase() === String(ai.recommended_title).toLowerCase());
  }
  if (!product || score < minScore) continue;
  const subject=String(ai.subject||'').replace(/[\r\n]+/g,' ').trim().slice(0,140);
  let html = String(ai.body_html || '').trim();
  if (!subject || !html) continue;
  html=html
    .replace(/<script[\s\S]*?<\/script>/gi,'')
    .replace(/<style[\s\S]*?<\/style>/gi,'')
    .replace(/\son\w+\s*=\s*(["']).*?\1/gi,'')
    .replace(/javascript:/gi,'');
  const productUrl = product.url;
  if (!html.includes(productUrl)) html += `<p><a href="${productUrl}">Voir le workflow</a></p>`;
  if (!/ne plus.*recontact|plus être recontact|ne pas.*recontact/i.test(html)) {
    html += `<p style="font-size:12px;color:#666">Si ce sujet ne vous concerne pas, répondez simplement que vous ne souhaitez plus être recontacté.</p>`;
  }
  if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(lead.email||''))) continue;
  out.push({json:{...lead,score,fit:String(ai.fit||''),produit:product.title,produitHandle:product.handle,produitUrl:productUrl,raison:String(ai.reason||''),angle:String(ai.angle||''),subject,html,statut:'A_VALIDER'}});
}
return out;

const maxDrafts = Number($('⚙️ Configuration prospection').first().json.maxDrafts || 10);
return $input.all()
  .sort((a,b) => Number(b.json.score || 0) - Number(a.json.score || 0))
  .slice(0, maxDrafts)
  .map((item,index)=>({json:{...item.json,rank:index+1}}));

const selected = $('🏆 Top prospects').all().map(i=>i.json);
const data = $getWorkflowStaticData('global');
data.preparedProspects = data.preparedProspects || {};
const now = Date.now();
for (const p of selected) if (p.prospectKey) data.preparedProspects[p.prospectKey] = now;
const avg = selected.length ? Math.round(selected.reduce((s,p)=>s+Number(p.score||0),0)/selected.length) : 0;
const products = [...new Set(selected.map(p=>p.produit).filter(Boolean))].slice(0,5);
const segments = [...new Set(selected.map(p=>p.categorie).filter(Boolean))].slice(0,8);
return [{json:{
  'Timestamp':new Date().toISOString(),
  'Période':'Prospection IA',
  'CA analysé':'',
  'Commandes':selected.length,
  'Produit prioritaire':products.join(' | '),
  'Objectif':'Trouver des prospects B2B pertinents pour N8N Market AI',
  'Action principale':`${selected.length} brouillon(s) Gmail créé(s) — validation humaine requise`,
  'SEO proposé':'',
  'Contenu proposé':selected.slice(0,5).map(p=>`${p.nom}: ${p.subject}`).join(' || '),
  'Segment client':segments.join(' | '),
  'Confiance':avg,
  'Validation requise':'OUI',
  'Statut':selected.length?'BROUILLONS_CREES':'AUCUN_PROSPECT',
  'Résumé IA':selected.slice(0,10).map(p=>`${p.rank}. ${p.nom} — ${p.score}/100 — ${p.produit} — ${p.email}`).join('\n')
}}];

parameters.content:
## N8N Market AI — Prospection IA — AUDITÉ V5

Ce workflow ne fait **aucun envoi automatique**. Il cherche des entreprises via SerpAPI/Google Local, lit leur site public, récupère un email professionnel public, qualifie le prospect avec OpenRouter, associe un produit réellement publié sur N8N Market AI et crée des **brouillons Gmail**.

### Configuration requise
1. Définir `SERPAPI_API_KEY` dans l'environnement n8n (aucune clé en clair dans le JSON).
2. Credential OpenRouter: `OpenRouter account`.
3. Credential Gmail: `FAOUZIGUERRIDA GMAIL`.
4. Credential Google Sheets: `Google Sheets account`.
5. Tester avec `▶️ Test manuel` avant activation.

### Corrections V5
- erreurs SerpAPI visibles au lieu d'être masquées;
- URLs prospects normalisées;
- lecture site forcée en texte avec redirections;
- emails techniques/indésirables filtrés et email du même domaine privilégié;
- réponse IA strictement liée au catalogue réel;
- HTML email nettoyé;
- score minimum 75/100;
- maximum 10 brouillons;
- déduplication de préparation 90 jours en production;
- expressions Google Sheets corrigées;
- aucune modification Shopify et aucun envoi automatique.

Important: la mémoire statique n8n est surtout destinée aux exécutions de production; pendant les tests manuels, vérifiez également les doublons visuellement.


- V5: pré-sélection limitée au nombre max de brouillons avant recherche de site, afin de limiter les appels SerpAPI.
- Si Google Maps ne fournit pas de site, une recherche Google ciblée tente de retrouver le site officiel avant lecture de la page et extraction d'un email public.

- V5.1: filtre ajouté pour écarter les centres commerciaux, hypermarchés et grandes galeries peu pertinents.

