const max = Number($('⚙️ Configuration prospection').first().json.maxDrafts || 10);
const seen = new Set();

const blockedName = /\b(topaze|hydrion|leclerc|cactus|auchan|shopping|centre commercial|centre-commercial|mall|hypermarch[eé]|supermarch[eé]|retail park|galerie commerciale)\b/i;
const blockedCategory = /\b(centre commercial|shopping mall|hypermarch[eé]|supermarch[eé]|grand magasin|retail park)\b/i;

return $input.all()
  .filter(item => {
    const j = item.json || {};
    const key = String(j.prospectKey || '').trim();
    if (!key || seen.has(key)) return false;
    seen.add(key);

    const nom = String(j.nom || '').trim();
    const categorie = String(j.categorie || '').trim();

    if (!nom) return false;
    if (blockedName.test(nom)) return false;
    if (blockedCategory.test(categorie)) return false;

    return true;
  })
  .sort((a,b) => {
    const aw = a.json.website ? 1 : 0;
    const bw = b.json.website ? 1 : 0;
    if (bw !== aw) return bw - aw;

    const ar = Number(a.json.reviews || 0);
    const br = Number(b.json.reviews || 0);
    if (br !== ar) return br - ar;

    return Number(b.json.rating || 0) - Number(a.json.rating || 0);
  })
  .slice(0, max)
  .map((item,index)=>({
    json:{...item.json,preRank:index+1},
    pairedItem:item.pairedItem
  }));

const leads = $('🏁 Pré-sélection prospects').all();
const inputs = $input.all();

const blocked = [
  'google.','facebook.com','instagram.com','linkedin.com','youtube.com',
  'tiktok.com','tripadvisor.','yelp.','editus.','yellow.lu','yellowpages.','wolt.',
  'ubereats.','just-eat.','booking.com','thefork.','pagesjaunes.','cybo.com','near-place.com'
];

function hostOf(u) {
  const m = String(u || '').trim().match(/^https?:\/\/([^\/?#:\s]+)/i);
  return m ? m[1].replace(/^www\./i, '').toLowerCase() : '';
}

function cleanWebsite(value){
  let website = String(value || '').trim();
  if (!website) return {website:'',domain:''};
  if (!/^https?:\/\//i.test(website)) website = 'https://' + website.replace(/^\/+/, '');
  const domain = hostOf(website);
  if (!domain || !domain.includes('.') || blocked.some(d => domain.includes(d))) return {website:'',domain:''};
  return {website,domain};
}

const out=[];

for(let i=0;i<inputs.length;i++){
  const lead=leads[i]?.json||{};
  const payload=inputs[i]?.json||{};

  let result = cleanWebsite(lead.website);
  if(!result.website) result = cleanWebsite(payload.knowledge_graph?.website);

  if(!result.website){
    const locals = Array.isArray(payload.local_results) ? payload.local_results : [];
    for(const p of locals){
      result = cleanWebsite(p.website || p.links?.website);
      if(result.website) break;
    }
  }

  if(!result.website){
    const results = Array.isArray(payload.organic_results) ? payload.organic_results : [];
    for(const r of results.slice(0,10)){
      result = cleanWebsite(r.link);
      if(result.website) break;
    }
  }

  out.push({
    json:{
      ...lead,
      website:result.website,
      domain:result.domain,
      siteLookupError: payload.error ? String(payload.error) : '',
      siteResolved: Boolean(result.website)
    },
    pairedItem:{item:i}
  });
}

return out;
